    fun app(name: String): String? = apps[name.trim().lowercase().removeSuffix(".exe")]

    fun site(name: String): String? {
        val host = name.trim().lowercase().removePrefix("www.")
        sites[host]?.let { return it }
        val parts = host.split('.')
        for (i in 1 until parts.size - 1) sites[parts.drop(i).joinToString(".")]?.let { return it }
        return null
    }
